import fs from "node:fs";
import { parseCsv, toCsv } from "./.cursor/scripts/tracker-lib.mjs";
const path = "upgrade/tracker.csv";
const t = parseCsv(fs.readFileSync(path, "utf8"));
const today = "2026-11-04";
const ev = "results/rehearsal-1.md";
const fr = "findings/rehearsal-1-timings.md";
const set = (id, status, notes, evidence) => {
  const r = t.rows.find((x) => x.ID === id);
  if (!r) throw new Error("missing " + id);
  if (r.Status !== status) r["Status since"] = today;
  r.Status = status; r.Notes = notes; r["Last checked"] = today;
  if (evidence !== undefined) r.Evidence = evidence;
};
set("G2.1", "Blocked", `Rehearsal 1 in-window steps took 59 min vs 45 min budget (75% of 60), 14 over; SOP in-window steps untimed (fence detail, reindex, stats coverage, statement set); clone shape not recorded (Q-18); sheet date conflict (Q-17); rehearsal 2 not run. See ${fr}#g21`, ev);
set("G2.5", "Blocked", `Rehearsal 1: debezium_orders "no gaps" is not an exactly-once sentinel log; search_feed not tested; no re-snapshot timing; neither name maps to a Consumer row (Q-19). See ${fr}#g25`, ev);
set("G2.6", "Blocked", `Rehearsal 1: rollback not timed (clone budget ran out); latest rollback decision time unknown. Rollback must take <=15.2 min for the T+41 upgrade to finish before the decision time (Inferred). See ${fr}#g26`, ev);
set("G2.2", "Waiting on customer", "Provider precheck ran in rehearsal 1 (5 min) but the clone precheck JSON was not pasted");
set("G2.3", "Waiting on customer", "Analyze ran in rehearsal 1 (8 min) but per-database stats coverage before and after was not pasted");
set("G2.7", "Waiting on customer", "Pooler and routing step ran in rehearsal 1 (2 min) but no routing check log was pasted");
set("B2-01", "Blocked", "Timing sheet attached, but the full rollback was not rehearsed (clone budget ran out); needs clone budget for the rollback rehearsal. Sheet date 2026-11-20 conflicts with today (Q-17)", ev);
set("B2-03", "In progress", `Rehearsal 1 parsed into ${fr}; upgrade/runbook.md does not exist yet (B1-10 not started), so measured times are not in a runbook; rehearsal 2 not run`);
const base = { Side: "Customer", "Run by": "Human", Status: "Waiting on customer", "Last checked": today, "Status since": today };
for (const id of ["Q-17","Q-18","Q-19"]) if (t.rows.some((r) => r.ID === id)) throw new Error("taken " + id);
t.rows.push(
  { ...base, ID: "Q-17", Type: "Question", Block: "2", Stream: "Runbook", Item: "Rehearsal 1 sheet is dated 2026-11-20, after today, and Block 1 has not exited: what date did it run, and which runbook version was rehearsed?", "Done when": "Confirmed date and runbook version", "Owner role": "DBA", Owner: "Sam Ortiz", "Depends on": "B2-01", Gates: "G2.1", Notes: `Conflict between ${ev} header and tracker Block 1 state` },
  { ...base, ID: "Q-18", Type: "Question", Block: "2", Stream: "Runbook", Item: "Did clone shop-clone-1 match production tier, storage, replica topology and minor version?", "Done when": "Clone describe output compared with production, or a signed scaling waiver", "Owner role": "DBA", Owner: "Sam Ortiz", "Depends on": "B2-01", Gates: "G2.1" },
  { ...base, ID: "Q-19", Type: "Question", Block: "2", Stream: "CDC", Item: "Which Consumer rows do debezium_orders and search_feed map to, and who owns them?", "Done when": "Consumer row with owner for each, or mapped to an existing row", "Owner role": "Program owner", Owner: "Dana Lee", "Depends on": "C-analytics-cdc", Gates: "G2.5 G0.5" },
);
fs.writeFileSync(path, toCsv(t.rows, t.header));
' && node .cursor/scripts/tracker-check.mjs upgrade/tracker.csv

